"""tool.py - Web Page Change Monitor with Telegram Alerts.

Tracks changes to a given URL by comparing SHA-256 hashes of its content.
Stores state in a local JSON cache and alerts via Telegram bot.
"""

import argparse
import hashlib
import json
import logging
import os
import sys
import requests

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s"
)
logger = logging.getLogger("page_watcher")


def load_state(cache_path: str) -> dict:
    if os.path.exists(cache_path):
        try:
            with open(cache_path, "r", encoding="utf-8") as f:
                return json.load(f)
        except (json.JSONDecodeError, OSError) as exc:
            logger.warning("Could not read state cache (%s). Starting fresh.", exc)
    return {}


def save_state(cache_path: str, state: dict) -> None:
    try:
        with open(cache_path, "w", encoding="utf-8") as f:
            json.dump(state, f, indent=2)
    except OSError as exc:
        logger.error("Failed to save state cache: %s", exc)


def send_telegram_alert(bot_token: str, chat_id: str, message: str, dry_run: bool = False) -> bool:
    if dry_run:
        logger.info("[DRY RUN] Telegram alert skipped: %s", message)
        return True

    api_url = f"https://api.telegram.org/bot{bot_token}/sendMessage"
    payload = {"chat_id": chat_id, "text": message, "parse_mode": "Markdown"}

    try:
        resp = requests.post(api_url, json=payload, timeout=10)
        resp.raise_for_status()
        logger.info("Telegram notification delivered successfully.")
        return True
    except requests.RequestException as exc:
        logger.error("Failed to dispatch Telegram alert: %s", exc)
        return False


def check_url(url: str, timeout: int = 15) -> tuple[str, int]:
    headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Monitor/1.0"}
    resp = requests.get(url, headers=headers, timeout=timeout)
    resp.raise_for_status()
    content_hash = hashlib.sha256(resp.content).hexdigest()
    return content_hash, len(resp.content)


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Check a web page for content changes and notify via Telegram."
    )
    parser.add_argument("--url", required=True, help="URL of the page to monitor")
    parser.add_argument("--token", default=os.getenv("TELEGRAM_BOT_TOKEN"), help="Telegram Bot Token")
    parser.add_argument("--chat-id", default=os.getenv("TELEGRAM_CHAT_ID"), help="Telegram Chat ID")
    parser.add_argument("--cache", default="monitor_cache.json", help="Path to state cache file")
    parser.add_argument("--dry-run", action="store_true", help="Log changes without sending Telegram message")
    parser.add_argument("--timeout", type=int, default=15, help="HTTP request timeout in seconds")

    args = parser.parse_args()

    if not args.dry_run and (not args.token or not args.chat_id):
        logger.error("Telegram credentials missing. Provide --token and --chat-id or use --dry-run.")
        sys.exit(1)

    logger.info("Fetching target URL: %s", args.url)
    try:
        current_hash, byte_size = check_url(args.url, timeout=args.timeout)
    except requests.RequestException as exc:
        logger.error("HTTP request failed: %s", exc)
        sys.exit(2)

    state = load_state(args.cache)
    last_hash = state.get(args.url)

    if last_hash is None:
        logger.info("Initial baseline recorded (%s bytes). Hash: %s", byte_size, current_hash[:12])
        state[args.url] = current_hash
        save_state(args.cache, state)
        return

    if current_hash != last_hash:
        logger.info("Change detected! Previous: %s, Current: %s", last_hash[:12], current_hash[:12])
        msg = f"*Page Change Detected*\n\nURL: {args.url}\nPayload Size: {byte_size} bytes"
        sent = send_telegram_alert(args.token, args.chat_id, msg, dry_run=args.dry_run)
        if sent:
            state[args.url] = current_hash
            save_state(args.cache, state)
    else:
        logger.info("No changes detected. Hash matches existing state (%s).", current_hash[:12])


if __name__ == "__main__":
    main()
